    "刹那": ["ボールを打った刹那、これはホームランだと確信した。","The instant I hit the ball, I was sure it was a home run."],
    "瞬時": ["ベテランの彼は、状況を瞬時に判断して的確に指示を出した。","Veteran that he is, he assessed the situation in an instant and gave precise instructions."],
    "一瞬": ["目を離した一瞬の隙に、子どもが人混みに紛れてしまった。","In the instant I looked away, my child got lost in the crowd."],
    "永らく": ["永らくご愛顧いただいた店も、今月末で閉店することになりました。","The shop you've patronized for so long will be closing at the end of this month."],
    "久しく": ["久しく会っていない旧友から、突然手紙が届いて驚いた。","I was surprised to suddenly receive a letter from an old friend I hadn't seen for a long time."],
