    "助長": ["匿名性が誹謗中傷を助長している面がある。","Anonymity tends to encourage slander and abuse."],
    "誘発": ["睡眠不足は集中力の低下を誘発する。","Lack of sleep induces a drop in concentration."],
    "誘導": ["係員が来場者を非常口へと誘導した。","The staff guided the visitors toward the emergency exit."],
    "招来": ["安易な妥協が後の混乱を招来した。","The easy compromise brought about the confusion that followed."],
    "余波": ["不祥事の余波で関連会社まで株価が下がった。","In the aftermath of the scandal, even affiliated companies saw their stock drop."],
