    "厳寒": ["厳寒の地で、隊員たちは凍えながら調査を続けた。","In the bitterly cold region, the team continued surveying while freezing."],
    "豪雨": ["局地的な豪雨で、駅前の道路が一気に冠水した。","A localized downpour flooded the road in front of the station in no time."],
