    "気象": ["登山前には必ず最新の気象情報を確認している。","Before climbing, I always check the latest weather information."],
    "気候": ["温暖な気候のおかげで、この地域は果樹栽培が盛んだ。","Thanks to the mild climate, fruit farming thrives in this region."],
    "大気": ["工場の排煙が大気を汚染し、住民が抗議している。","Smoke from the factory pollutes the air, and residents are protesting."],
    "生物": ["深海には、まだ知られていない生物が数多くいる。","The deep sea is home to many organisms still unknown to us."],
    "植生": ["山火事の後、植生が回復するには長い年月がかかる。","After a wildfire, it takes many years for vegetation to recover."],
    "絶滅": ["乱獲によって、その魚は絶滅の危機に瀕している。","Overfishing has pushed that fish to the brink of extinction."],
