    "傑作": ["この映画は、監督の数ある作品の中でも屈指の傑作だ。","This film is among the finest masterpieces in the director's body of work."],
    "駄作": ["話題作だと期待したのに、ただの駄作でがっかりした。","I expected a hit, but it was just a flop and I was let down."],
