    "教鞭": ["彼は定年まで四十年間、地元の高校で教鞭を執った。","He stood at the chalkboard at the local high school for forty years until retirement."],
    "門下": ["あの作曲家の門下からは、世界的な指揮者が何人も育っている。","Several world-class conductors have come out of that composer's tutelage."],
    "師弟": ["二人は三十年来の師弟だが、今では対等な研究仲間でもある。","The two have been master and disciple for thirty years, but now they're equal research partners as well."],
    "後進": ["第一線を退き、これからは後進の指導に専念したい。","Having stepped back from the front lines, I want to devote myself to mentoring the younger generation."],
