  // ───────────── KANJI ─────────────
  // Each: [kanji, kun, on, meaning]
  function kanjiCards(deck, level, items) {
    return items.map((it) => ({
      id: "ja:kanji:" + it[0],
      lang: "ja",
      level,
      deck,
      type: "kanji",
      jp: it[0],
      kun: it[1],
      on: it[2],
      en: it[3],
      de: DE_VOCAB[it[0]] || "",
      ex: SIMPLE_EX[it[0]] ? [SIMPLE_EX[it[0]]] : [],
      front: it[0],
      back: it[3],
      hint: (it[1] ? "kun: " + it[1] : "") + (it[2] ? "  on: " + it[2] : ""),
      speakText: it[1] || it[2] || it[0]
    }));
  }

